ROOT=pathlib.Path(__file__).resolve().parents[3];OUT=ROOT/'results/real-app/multi-bundler-v1';BASE=ROOT/'baselines/bundling-connectivity-v1-2026-10-22';baseline=json.load(open(BASE/'BASELINE.json'));subjects=[s for s in baseline['subjects'] if s['bundler']!='esbuild'];summaries=[];rows=[]
