for d in summaries:
 v={x['variant']:x for x in d['variants']};repo_rows.append({'bundler':d['bundler'],'repo':d['repo'],'commit':d['commit'],'targets':v['baseline-control']['targets'],**{name:v[name]['recovered']for name in variants},'source_extraction_ms':d['analysis']['source']['elapsedMs'],'bundle_extraction_ms':d['analysis']['bundle']['elapsedMs'],'source_rss_mib':round(d['analysis']['source']['stats']['rssBytes']/1048576),'bundle_rss_mib':round(d['analysis']['bundle']['stats']['rssBytes']/1048576),'source_ast_nodes':d['analysis']['source']['stats']['astNodes'],'bundle_ast_nodes':d['analysis']['bundle']['stats']['astNodes'],'source_code_bytes':d['analysis']['source']['codeBytes'],'bundle_code_bytes':d['analysis']['bundle']['codeBytes'],'cross_chunk_edges':d['edgeStats']['crossChunkAdded']})
